import Foundation
import AppKit

@MainActor
public final class ClipboardMonitor {
    /// Standard Maccy/NSPasteboard marker types for concealed, transient, or password-manager content
    public static let ignoredTypes: Set<String> = [
        "org.nspasteboard.TransientType",
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "com.typeit4me.clipping",
        "de.petermaurer.TransientPasteboardType",
        "net.antelle.keeweb"
    ]

    /// Maximum single payload size to store (25 MB) to keep memory and disk fast
    private static let maxSinglePayloadBytes: Int = 25 * 1024 * 1024

    private let pasteboard: NSPasteboard
    private let store: HistoryStore
    private let pollInterval: TimeInterval
    private var timer: Timer?
    private(set) public var lastChangeCount: Int
    private var ignoredChangeCount: Int?

    public init(
        pasteboard: NSPasteboard = .general,
        store: HistoryStore,
        pollInterval: TimeInterval = 0.25
    ) {
        self.pasteboard = pasteboard
        self.store = store
        self.pollInterval = pollInterval
        self.lastChangeCount = pasteboard.changeCount
    }

    public func start() {
        stop()
        lastChangeCount = pasteboard.changeCount
        timer = Timer.scheduledTimer(withTimeInterval: pollInterval, repeats: true) { [weak self] _ in
            Task { @MainActor [weak self] in
                self?.checkForChanges()
            }
        }
        if let timer = timer {
            RunLoop.main.add(timer, forMode: .common)
        }
    }

    public func stop() {
        timer?.invalidate()
        timer = nil
    }

    /// Tells the monitor to ignore a specific `changeCount` produced when CMDV itself writes to NSPasteboard during paste.
    public func ignoreChangeCount(_ count: Int) {
        self.ignoredChangeCount = count
        self.lastChangeCount = count
    }

    /// Checks `NSPasteboard` and records a new `ClipboardItem` if `changeCount` advanced.
    public func checkForChanges() {
        let currentCount = pasteboard.changeCount
        guard currentCount != lastChangeCount else { return }
        lastChangeCount = currentCount

        if let ignored = ignoredChangeCount, currentCount == ignored {
            ignoredChangeCount = nil
            return
        }

        if let item = Self.extractItem(from: pasteboard) {
            store.add(item)
        }
    }

    /// Extracts a `ClipboardItem` (text, image, file, or binary payload) from the given `NSPasteboard`.
    public static func extractItem(from pasteboard: NSPasteboard, now: Date = Date()) -> ClipboardItem? {
        guard let pbItems = pasteboard.pasteboardItems, !pbItems.isEmpty else {
            return nil
        }

        // Check if any item contains a concealed or transient marker
        for pbItem in pbItems {
            let typeStrings = Set(pbItem.types.map(\.rawValue))
            if !typeStrings.isDisjoint(with: ignoredTypes) {
                return nil
            }
        }

        let frontApp = NSWorkspace.shared.frontmostApplication
        let sourceBundleID = frontApp?.bundleIdentifier
        let sourceAppName = frontApp?.localizedName

        // Collect all raw payloads from the first primary pasteboard item
        var payloads: [String: Data] = [:]
        var totalBytes = 0
        if let primary = pbItems.first {
            for type in primary.types {
                if let data = primary.data(forType: type),
                   !data.isEmpty,
                   data.count <= maxSinglePayloadBytes {
                    payloads[type.rawValue] = data
                    totalBytes += data.count
                }
            }
        }

        // 1. Check for copied files in Finder (public.file-url)
        var extractedFilePaths: [String] = []
        if let urls = pasteboard.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            extractedFilePaths = urls.map(\.path)
        }

        // 2. Check for image content (screenshots, copied pictures, binary image data)
        var pngData: Data?
        var imageWidth: Int?
        var imageHeight: Int?
        var thumbnailData: Data?

        let hasImageType = pasteboard.types?.contains(where: {
            $0 == .png || $0 == .tiff || $0.rawValue == "public.jpeg" || $0.rawValue == "public.heic"
        }) ?? false

        if hasImageType && extractedFilePaths.isEmpty {
            if let directPNG = pasteboard.data(forType: .png),
               let image = NSImage(data: directPNG) {
                pngData = directPNG
                let rep = image.representations.first
                imageWidth = rep?.pixelsWide ?? Int(image.size.width)
                imageHeight = rep?.pixelsHigh ?? Int(image.size.height)
                thumbnailData = makeThumbnailPNG(from: image, maxDimension: 360) ?? directPNG
                payloads[NSPasteboard.PasteboardType.png.rawValue] = directPNG
            } else if let tiffData = pasteboard.data(forType: .tiff),
                      let image = NSImage(data: tiffData),
                      let convertedPNG = pngRepresentation(from: image) {
                pngData = convertedPNG
                let rep = image.representations.first
                imageWidth = rep?.pixelsWide ?? Int(image.size.width)
                imageHeight = rep?.pixelsHigh ?? Int(image.size.height)
                thumbnailData = makeThumbnailPNG(from: image, maxDimension: 360) ?? convertedPNG
                payloads[NSPasteboard.PasteboardType.png.rawValue] = convertedPNG
            }
        }

        // 3. Check for plain text string
        let plainText = pasteboard.string(forType: .string)

        // Determine primary kind
        if let pngData = pngData {
            let hash = ClipboardItem.computeHash(
                kind: .image,
                text: nil,
                imageData: pngData,
                fileURLs: []
            )
            return ClipboardItem(
                createdAt: now,
                kind: .image,
                textContent: plainText,
                imageWidth: imageWidth,
                imageHeight: imageHeight,
                byteSize: max(totalBytes, pngData.count),
                sourceAppBundleID: sourceBundleID,
                sourceAppName: sourceAppName,
                contentHash: hash,
                inlinePayloads: payloads,
                thumbnailPNGData: thumbnailData
            )
        }

        if !extractedFilePaths.isEmpty {
            // Also generate a thumbnail if a single image file was copied in Finder
            if extractedFilePaths.count == 1,
               let firstPath = extractedFilePaths.first,
               let fileImage = NSImage(contentsOfFile: firstPath) {
                thumbnailData = makeThumbnailPNG(from: fileImage, maxDimension: 320)
                let rep = fileImage.representations.first
                imageWidth = rep?.pixelsWide ?? Int(fileImage.size.width)
                imageHeight = rep?.pixelsHigh ?? Int(fileImage.size.height)
            }

            let hash = ClipboardItem.computeHash(
                kind: .file,
                text: plainText,
                imageData: nil,
                fileURLs: extractedFilePaths
            )
            return ClipboardItem(
                createdAt: now,
                kind: .file,
                textContent: plainText,
                fileURLs: extractedFilePaths,
                imageWidth: imageWidth,
                imageHeight: imageHeight,
                byteSize: totalBytes,
                sourceAppBundleID: sourceBundleID,
                sourceAppName: sourceAppName,
                contentHash: hash,
                inlinePayloads: payloads,
                thumbnailPNGData: thumbnailData
            )
        }

        if let text = plainText, !text.isEmpty {
            let hash = ClipboardItem.computeHash(
                kind: .text,
                text: text,
                imageData: nil,
                fileURLs: []
            )
            let utf8Data = Data(text.utf8)
            if payloads[NSPasteboard.PasteboardType.string.rawValue] == nil {
                payloads[NSPasteboard.PasteboardType.string.rawValue] = utf8Data
            }
            return ClipboardItem(
                createdAt: now,
                kind: .text,
                textContent: text,
                byteSize: max(totalBytes, utf8Data.count),
                sourceAppBundleID: sourceBundleID,
                sourceAppName: sourceAppName,
                contentHash: hash,
                inlinePayloads: payloads
            )
        }

        // 4. Fallback for arbitrary binary clipboard objects (PDF, custom app binary data, etc.)
        if !payloads.isEmpty {
            let sortedConcatenated = payloads.keys.sorted().reduce(into: Data()) { acc, key in
                if let d = payloads[key] { acc.append(d) }
            }
            let hash = ClipboardItem.computeHash(
                kind: .binary,
                text: nil,
                imageData: nil,
                fileURLs: [],
                fallbackData: sortedConcatenated
            )
            return ClipboardItem(
                createdAt: now,
                kind: .binary,
                byteSize: totalBytes,
                sourceAppBundleID: sourceBundleID,
                sourceAppName: sourceAppName,
                contentHash: hash,
                inlinePayloads: payloads
            )
        }

        return nil
    }

    // MARK: - Image Utilities

    public static func pngRepresentation(from image: NSImage) -> Data? {
        guard let tiff = image.tiffRepresentation,
              let bitmap = NSBitmapImageRep(data: tiff) else {
            return nil
        }
        return bitmap.representation(using: .png, properties: [:])
    }

    public static func makeThumbnailPNG(from image: NSImage, maxDimension: CGFloat) -> Data? {
        let originalSize = image.size
        guard originalSize.width > 0 && originalSize.height > 0 else { return nil }

        let scale = min(1.0, maxDimension / max(originalSize.width, originalSize.height))
        let targetSize = NSSize(
            width: max(1, round(originalSize.width * scale)),
            height: max(1, round(originalSize.height * scale))
        )

        let rep = NSBitmapImageRep(
            bitmapDataPlanes: nil,
            pixelsWide: Int(targetSize.width),
            pixelsHigh: Int(targetSize.height),
            bitsPerSample: 8,
            samplesPerPixel: 4,
            hasAlpha: true,
            isPlanar: false,
            colorSpaceName: .calibratedRGB,
            bytesPerRow: 0,
            bitsPerPixel: 0
        )
        guard let bitmapRep = rep else { return pngRepresentation(from: image) }

        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: bitmapRep)
        NSGraphicsContext.current?.imageInterpolation = .high
        image.draw(
            in: NSRect(origin: .zero, size: targetSize),
            from: NSRect(origin: .zero, size: originalSize),
            operation: .copy,
            fraction: 1.0
        )
        NSGraphicsContext.restoreGraphicsState()

        return bitmapRep.representation(using: .png, properties: [:])
    }
}
